#include <linux/mutex.h>
#include <linux/cdev.h>
#include <linux/fuse.h>

int cuse_channel_release(struct inode *inode, struct file *file) {
    struct fuse_conn *conn = fuse_get_conn(inode);
    int res;

    mutex_lock(&conn->lock);
    if (conn->cdev) {
        unregister_chrdev_region(conn->cdev, 1);
        cdev_del(conn->cdev);
        conn->cdev = NULL;
    }
    list_del(&conn->entry);
    mutex_unlock(&conn->lock);

    res = fuse_dev_release(inode, file);
    fuse_put_conn(conn);
    return res;
}
